// Healed 2026-11-03 by autotest-writer (not run): phone → uniquePhone() (22.10 unique-phone rule). The «פרופיל אנונימי» radio here is the SUBMISSION dialog — still valid.
// Creates data: candidate «QA-AUTO-d9db64-<ts> נועה לוי» (no delete in UI — logged for manual cleanup).
// NEVER clicks «סיום והגשה» — nothing is submitted to J-49.
// AI is not deterministic: only "not empty" + "no forbidden pattern" are asserted.
import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, fillStep1, forbiddenIn, stamp, uniquePhone } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const ts = stamp();
const FIRST = `QA-AUTO-d9db64-${ts} נועה`;
const NAME = `${FIRST} לוי`;
const FIELD = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';
const J49 = '/collaborations/7e4ad713-60a0-4e68-9926-56e0ee667584';
const GENERATIONS = 3;

test.describe('AI texts for a candidate with minimal data (#d9db64)', () => {
  test.afterAll(() => {
    console.warn(`[test-data] created candidate «${NAME}» (hunter_plus), not submitted — the UI has no delete; clean up manually`);
  });

  test('Submit dialog: AI summary and strengths stay clean on 3 regenerations, job not presented as the fit @desktop @data #d9db64', async ({ page }) => {
    test.setTimeout(300_000);
    // 1. Minimal candidate → «סיום»
    const add = await openAddCandidate(page);
    await fillStep1(add, { first: FIRST, last: 'לוי', phone: uniquePhone(), field: FIELD });
    await expect(page.locator('#c-ai-summary')).toHaveValue(/\S/, { timeout: 60_000 });
    await add.getByRole('button', { name: 'סיום', exact: true }).click();
    await expect(add).toBeHidden({ timeout: 30_000 });

    // 2. J-49 → «הגשת <candidate> למשרה»
    await page.goto(J49);
    const drawer = page.getByRole('dialog', { name: 'פרטי המשרה' });
    await expect(drawer.getByRole('heading', { name: 'QA company post test' })).toBeVisible();
    await drawer.getByRole('searchbox', { name: 'חיפוש מועמד' }).fill(ts);
    await drawer.getByRole('button', { name: `הגשת ${NAME} למשרה` }).click();

    // 3. Anonymous + no NDA → «המשך»
    const choose = page.getByRole('dialog', { name: new RegExp(`^הגשת .*${ts}`) });
    await expect(choose.getByRole('heading', { name: 'האם להגיש פרופיל מלא או אנונימי?' })).toBeVisible();
    await choose.getByText('פרופיל אנונימי', { exact: true }).click();
    await expect(choose.getByRole('radio', { name: /^פרופיל אנונימי/ })).toBeChecked();
    await expect(choose.getByRole('radio', { name: /^אין צורך ב-NDA/ })).toBeChecked();

    const submitDialog = page.getByRole('dialog', { name: `הגשת מועמד: ${NAME}` });
    const summary = submitDialog.getByRole('textbox', { name: 'תקציר המועמד' });
    const strengths = submitDialog.getByRole('textbox', { name: 'חוזקות' });

    for (let gen = 1; gen <= GENERATIONS; gen++) {
      await choose.getByRole('button', { name: 'המשך', exact: true }).click();

      // 4. Wait for both AI fields, read them
      await expect(summary).toHaveValue(/\S/, { timeout: 60_000 });
      await expect(strengths).toHaveValue(/\S/, { timeout: 60_000 });
      await expect(summary).not.toHaveAttribute('placeholder', /יוצר/);
      await expect(strengths).not.toHaveAttribute('placeholder', /יוצר/);
      const s = await summary.inputValue();
      const st = await strengths.inputValue();
      test.info().annotations.push({ type: `gen${gen}-summary`, description: s }, { type: `gen${gen}-strengths`, description: st });

      expect(forbiddenIn(s, { jobFit: true }), `gen ${gen} summary: «${s}»`).toEqual([]);
      if (st.trim() !== 'לא צוין') expect(forbiddenIn(st, { jobFit: true }), `gen ${gen} strengths: «${st}»`).toEqual([]);

      // 5. «חזרה» → back to the first step (regenerate on the next «המשך»)
      await submitDialog.getByRole('button', { name: 'חזרה', exact: true }).click();
      await expect(submitDialog).toBeHidden();
      await expect(choose.getByRole('button', { name: 'המשך', exact: true })).toBeEnabled();
    }

    // 6. Close WITHOUT «סיום והגשה»
    await choose.getByRole('button', { name: 'סגירה' }).click();
    await expect(choose).toBeHidden();
    await expect(drawer.getByRole('button', { name: `הגשת ${NAME} למשרה` })).toBeVisible();
  });
});
